'use strict';
// Business result entry points reuse each tool's result viewer and exporters.
const trBase={tasksPage,workbench,handleAction,isLocked,exportRows,doExport};
const TR_OUTPUTS={
 extract:['提取信息表','字段值、未提取项与原文证据，便于汇总和核验。'],
 word:['词频明细','词语、出现次数和来源文件，用于了解资料中的重点内容。'],
 meeting:['会议与议题清单','会议、议题、金额、参会人员与来源，便于追踪决策事项。'],
 theme:['主题归纳与基础信息','按主题整理事项，保留基础信息与原文依据。'],
 timeline:['事项时间轴','日期、事项及原文来源，便于梳理业务过程。'],
 risk:['风险线索清单','检查点、线索、资料不足项与依据，供审计人员逐项核验。'],
 contract:['合同条款检查表','条款、检查结论与原文依据，便于检查合同约定。'],
 bidding:['招投标检查表','按项目与分析环节整理检查内容及来源。'],
 prepaid:['计费约定明细','提取合同计费约定；费用报告在填写基数并完成计算后下载。'],
 engineering:['项目关系候选表','重复项目和主子项目候选、评分与源行，供人工核对。'],
 association:['两表关联候选表','两表对应记录、匹配分数与理由，供人工确认关联关系。']
};
function trMode(){const parts=location.hash.slice(1).split('/');return state.view==='tool'&&currentTask()&&['config','download'].includes(parts[3])?parts[3]:'';}
function trHasResult(t){return !tcMerge(t)&&!!tcResolve(t)&&!tcBusy(t)&&(!['failed','stopped'].includes(t.status))&&(tcRows(t).length>0||t.status==='completed'||t.status==='awaiting');}
function trCanDownload(t){const ids=[...new Set([...(t.ids||[]),...(t.config?.merge?Object.values(t.attachments||{}).flat():[])])];return trHasResult(t)&&tcRows(t).length>0&&ids.every(id=>{const d=file(id);return d&&!d.deleted&&auditFileAccess(d).read&&auditFileAccess(d).download;});}
function trAction(label,icon,action,t,disabled='',title=''){return B('<span>'+label+'</span>',action,'ghost sm tr-action tr-action-'+action.slice(3),'data-id="'+E(t.id)+'" title="'+E(title||label)+'" '+(disabled?'disabled aria-label="'+E(label+'：'+disabled)+'"':''));}
tasksPage=function(){const html=trBase.tasksPage();if(tmView.mode!=='records'){const root=document.createElement('div');root.innerHTML=html;root.querySelector('.tc-page')?.classList.add('tr-task-actions');root.querySelectorAll('[data-tc-row]').forEach(row=>{const t=state.tasks.find(t=>t.id===row.dataset.tcRow);row.querySelector('.tc-actions>div').innerHTML=trOperations(t);});return root.innerHTML;}const root=document.createElement('div');root.innerHTML=html;root.querySelector('.tc-page').classList.add('tr-records');const heads=root.querySelectorAll('.tc-table th');['选择','分析名称','使用工具 / 范围','分析状态','分析成果','提交时间','操作'].forEach((n,i)=>heads[i].textContent=n);const query=root.querySelector('#tc-query');query.placeholder='搜索分析名称或备注';query.setAttribute('aria-label','搜索分析名称或备注');
 root.querySelector('.tc-time-col').remove();heads[5].remove();root.querySelectorAll('[data-tc-row]').forEach(row=>{const t=state.tasks.find(t=>t.id===row.dataset.tcRow);const time=row.children[5];row.querySelector('.tc-name').insertAdjacentHTML('afterend','<small class="tr-submitted">'+time.innerHTML+'</small>');time.remove();if(!tcBusy(t))row.querySelector('.tc-phase')?.remove();if(t.status==='failed'&&t.error)row.querySelector('.tc-output+small').textContent=t.error;row.querySelector('.tc-actions>div').innerHTML=trOperations(t);
 });
 root.querySelector('.tc-footnote').textContent='查看结果核对分析内容与依据；任务信息查看资料、配置和运行情况；导出数据用于后续整理。';return root.innerHTML;};
function trHeader(t,mode){return '<header class="tr-page-head"><div>'+B(I('back','icon-sm')+'分析结果','tr-back','ghost sm')+'<div><h1>'+E(tool(tcResolve(t)).name)+' · '+(mode==='config'?'执行配置':'导出数据')+'</h1><p title="'+E(t.name)+'">'+E(t.name)+'</p></div></div><nav aria-label="本次分析操作">'+trAction('查看结果','','tr-result',t,trHasResult(t)?'':'暂无可查看结果')+trAction('任务信息','','tr-info',t)+trAction('导出数据','','tr-download',t,trCanDownload(t)?'':'暂无可导出数据')+'</nav></header>';}
function trConfigPage(t){const root=document.createElement('div');root.innerHTML=configPanel();root.querySelectorAll('.ef-step,.tw-step').forEach(n=>n.remove());root.querySelectorAll('[data-action="nav-templates"],[data-action="save-template"],[data-action="v2-export-config"],[data-action="lexicon"],[data-action="attachments"],[data-action="ew-import"],[data-action="xt-delete"]').forEach(n=>n.remove());root.querySelectorAll('.config-toolbar:empty,.ew-template-actions:empty,.aw-config-links:empty').forEach(n=>n.remove());root.querySelectorAll('input,select,textarea').forEach(n=>{if(n.tagName==='TEXTAREA'||n.tagName==='INPUT'&&!['checkbox','radio'].includes(n.type))n.readOnly=true;else n.disabled=true;});
 const specific=t.toolId==='association'?'<section class="tr-extra"><h3>两表对应与比较规则</h3><p>'+E(t.tableAName||'表一')+' ↔ '+E(t.tableBName||'表二')+'</p>'+B('查看字段、评分与硬规则','v2-association','sm')+'</section>':t.toolId==='bidding'?'<section class="tr-extra"><h3>项目与资料角色</h3>'+t.projects.map(p=>'<details><summary>'+E(p.name)+'</summary><p>招标资料：'+(p.tender||[]).map(id=>E(file(id)?.name||'原资料已移除')).join('、')+'</p>'+p.bidders.map(b=>'<p>投标单位 · '+E(b.name)+'：'+b.files.map(id=>E(file(id)?.name||'原资料已移除')).join('、')+'</p>').join('')+'</details>').join('')+'</section>':'';
 const attachments=Object.entries(t.attachments||{}).filter(([,ids])=>ids.length);return trHeader(t,'config')+'<div class="tr-config-layout"><aside class="tr-scope"><h2>本次分析资料 <strong>'+tcCount(t).total+'</strong></h2><p>查看提交分析时的资料范围和关联附件。</p>'+B(I('folder','icon-sm')+'查看资料清单','tr-sources','sm','data-id="'+E(t.id)+'"')+'<dl><dt>使用工具</dt><dd>'+E(tool(t.toolId).name)+'</dd><dt>提交时间</dt><dd>'+tcDate(t.created)+'</dd><dt>分析状态</dt><dd>'+tag(...tcLabel(t))+'</dd><dt>本次备注</dt><dd>'+E(t.notes||'未填写')+'</dd></dl>'+(attachments.length?'<h3>关联附件</h3><p>'+attachments.length+' 份主文件关联附件，'+(t.config?.merge?'本次合并附件分析。':'以执行配置中的处理规则为准。')+'</p>'+B('查看附件清单','tr-attachments','sm','data-id="'+E(t.id)+'"'):'')+'</aside><section class="tr-config-content"><p class="tr-readonly">'+I('clock','icon-sm')+'本次执行时的配置，只读保留。</p>'+specific+root.innerHTML+'</section></div>';}
function trDownloadPage(t){const id=tcResolve(t),spec=TR_OUTPUTS[id],ready=trCanDownload(t),card=(key,icon,name,desc,formats,enabled=true)=>'<article class="tr-download-card">'+I(icon)+'<div><h2>'+name+'</h2><p>'+desc+'</p><small>'+formats+'</small></div>'+B(I('download','icon-sm')+'下载','tr-artifact','sm','data-kind="'+key+'" '+(ready&&enabled?'':'disabled'))+'</article>';return trHeader(t,'download')+'<section class="tr-download-content"><div class="tr-download-summary">'+tag(...tcLabel(t))+'<span>'+E(tcOutput(t).text)+'</span></div><p class="tr-download-intro">选择需要带走的结果，下载时可确认文件格式与资料范围。</p>'+(!ready?'<p class="tr-download-warning">暂无可下载结果，或来源资料的下载权限已变化。</p>':'')+(['partial','awaiting'].includes(t.status)||t.summaryFailed?'<p class="tr-download-warning">'+(t.status==='awaiting'?'计费约定已提取，尚未生成费用报告。':t.summaryFailed?'当前可下载基础信息，主题归纳尚未完成。':'仅下载已返回的结果；未完成和失败资料不计入结果明细。')+'</p>':'')+card('main','grid',spec[0],spec[1],'Excel / CSV / Markdown / JSON')+(id==='word'?card('cloud','cloud','词云图片','展示本次词频分布，便于汇报与展示。','PNG'):id==='meeting'?card('risk','shield','会议风险分析报告',t.meetingRisk?'风险事项、原文证据与核验建议。':'尚未生成，可到结果页继续分析会议风险。','Word / Excel / Markdown / JSON',!!t.meetingRisk)+card('qa','message','会议问答记录',t.chats?.length?'保留本次问答内容及关联会议来源。':'本次尚无问答记录。','Markdown / JSON',!!t.chats?.length):id==='contract'?card('contract','file','合同分析报告','按检查规则整理条款结论及原文依据。','TXT'):id==='prepaid'?card('fee','calculator','费用计算报告',t.fee!=null?'计费约定、基数、计算费用与合同来源。':'请先在结果页填写计费基数并完成计算。','TXT',t.fee!=null):'')+'<p class="tr-download-note">分析结果供审计核验使用；风险线索和关联候选不等于已确认的审计问题。</p></section>';}
workbench=function(){
 const mode=trMode(),t=currentTask();
 if(mode)return '<div class="tr-detail-page tr-'+mode+'-page">'+(mode==='config'?trConfigPage(t):trDownloadPage(t))+'</div>';
 if(!t)return trBase.workbench();
 // Result pages use the full workspace; input selection remains in preparation.
 if(state.toolId==='extract'&&efView.panel==='materials')efView.panel='preview';
 const root=document.createElement('div');root.innerHTML=trBase.workbench();
 root.firstElementChild?.classList.add('tr-result-only');
 root.querySelectorAll('.ew-grid>.ew-materials,.workbench>.workset,.ef-mobile-tabs [data-panel="materials"]').forEach(el=>el.remove());
 return root.innerHTML;
};
isLocked=function(){return trMode()==='config'||trBase.isLocked();};
function trOpen(t,mode){if(!t||!tcResolve(t))return toast('工具类型尚未确认，无法打开对应页面。');if(mode==='download'&&!trCanDownload(t))return toast('暂无可下载结果，或来源资料的下载权限已变化。');if(mode==='result'&&!trHasResult(t))return toast('当前暂无可查看结果，可查看配置或查看运行监控。');openTask(t.id);if(mode!=='result'){history.replaceState(history.state,'','#tool/'+tcResolve(t)+'/'+encodeURIComponent(t.id)+'/'+mode);render();}}
handleAction=function(action,el){const t=state.tasks.find(t=>t.id===el.dataset.id)||currentTask();if(action==='tr-info'){tcView.infoTab='overview';return openModal(tcMerge(t)?'tc-export-detail':'tc-info',{id:t.id,monitor:state.view==='tasks'&&tmView.mode==='monitor'});}if(['tr-result','tr-download'].includes(action)&&tcMerge(t))return openModal('tc-export-detail',{id:t.id});if(['tr-result','tr-config','tr-download'].includes(action))return trOpen(t,action.slice(3));if(action==='tr-back'){tmView.mode='records';return nav('tasks');}if(action==='tr-sources'){tcView.infoTab='sources';return openModal('tc-info',{id:t.id});}if(action==='tr-attachments')return openModal('tr-attachments',{id:t.id});if(action==='tr-artifact'){const task=currentTask();if(!trCanDownload(task))return toast('暂无可下载结果，或资料下载权限已变化。');const kind=el.dataset.kind;if(kind==='cloud'){av('word').resultQuery='';av('word').resultScope='all';av('word').resultFolder=null;av('word').top=null;return awDownloadCloud();}if(kind==='contract'||kind==='fee')return trBase.handleAction(kind==='contract'?'download-contract':'download-fee',el);if(kind==='risk'&&!task.meetingRisk||kind==='qa'&&!task.chats?.length)return toast('尚未生成此项结果。');ws().subtab=kind==='risk'?'risk':kind==='qa'?'qa':task.toolId==='meeting'?'regular':'main';return trBase.handleAction('export',el);}if(trMode()==='download'&&action==='do-export'&&!trCanDownload(currentTask()))return toast('资料下载权限已变化，请重新核对。');return trBase.handleAction(action,el);};
const trModalBase=modalContent;
modalContent=function(){if(modal!=='tr-attachments'){const html=trModalBase();if(modal==='export'&&trMode()==='download'){const root=document.createElement('div');root.innerHTML=html;const option=root.querySelector('#export-format option[value=xlsx]');if(option)option.setAttribute('selected','');return root.innerHTML;}return html;}const t=state.tasks.find(t=>t.id===modalData.id);return modalFrame('本次关联附件',E(t?.name),'只读查看执行时保存的附件关联。'+simpleTable(['主文件','关联附件'],Object.entries(t?.attachments||{}).filter(([,ids])=>ids.length).map(([id,ids])=>[E(file(id)?.name||'原资料已移除'),ids.map(a=>E(file(a)?.name||'原资料已移除')).join('、')]),true),B('关闭','close-modal'),'medium');};
render();
// Keep business column labels and traceability in the remaining tabular tool exports.
const TR_TABLE_TOOLS=['contract','bidding','prepaid','engineering','association'];
exportRows=function(t,scope='all'){
 if(!TR_TABLE_TOOLS.includes(t.toolId))return trBase.exportRows(t,scope);
 const rows=tcRows(t).filter(r=>scope==='all'||r.doc===scope||r.docs?.includes(scope));
 const labels={doc:'来源文件',other:'对照文件',title:t.toolId==='bidding'?'所属项目':'资料名称',unit:t.toolId==='bidding'?'投标单位 / 招标方':'涉及单位',amount:'金额与单位',date:'日期',topic:'事项主题',excerpt:'原文依据',check:'检查内容',judgment:'检查结果',detail:'分析说明',refs:'关联来源',kind:'候选关系',a:t.toolId==='association'?(t.tableAName||'表一')+'记录':'项目一',b:t.toolId==='association'?(t.tableBName||'表二')+'记录':'项目二',score:'匹配评分',rows:'来源行内容'};
 const keys=[...new Set(rows.flatMap(Object.keys))],value=(k,v)=>['doc','other'].includes(k)?file(v)?.name||'原资料已移除':k==='refs'?(v||[]).map(id=>file(id)?.name||'原资料已移除').join('；'):k==='kind'?({duplicate:'疑似重复项目',parent:'主子项目候选'})[v]||v:typeof v==='object'?JSON.stringify(v):v??'';
 return [keys.map(k=>labels[k]||k),...rows.map(r=>keys.map(k=>value(k,r[k])))];
};
doExport=function(){const t=currentTask();if(!t||!TR_TABLE_TOOLS.includes(t.toolId))return trBase.doExport();if(!trCanDownload(t))return toast('暂无可下载结果，或资料下载权限已变化。');const format=$('#export-format').value;if(format!=='xlsx')return trBase.doExport();const scope=$('#export-scope').value,matrix=exportRows(t,scope);if(matrix.length<2)return toast('当前资料范围没有可下载结果。');const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(matrix),'分析明细');const snapshot={config:t.config,projects:t.projects,modes:t.modes,tableA:t.tableA,tableB:t.tableB,tableAName:t.tableAName,tableBName:t.tableBName,attachments:t.attachments},text=JSON.stringify(snapshot);const cfg=[['分析名称',t.name],['使用工具',tool(t.toolId).name],['提交时间',tcDate(t.created)],['下载范围',scope==='all'?'本次全部结果':file(scope)?.name||scope],['备注',t.notes||'']];for(let i=0;i<text.length;i+=30000)cfg.push(['执行配置 '+(1+i/30000),text.slice(i,i+30000)]);XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(cfg),'本次分析配置');XLSX.writeFile(wb,(t.name||tool(t.toolId).name).replace(/[\\/:*?"<>|]/g,'-')+'.xlsx');closeModal();};
// Restore a validated history subpage after all existing tool routers have initialized.
try{const [view,toolId,encoded,mode]=taskResultEntryHash.slice(1).split('/');if(view==='tool'&&['config','download'].includes(mode)){const id=decodeURIComponent(encoded||''),t=state.tasks.find(t=>t.id===id&&!tcMerge(t)&&tcResolve(t)===toolId);if(t){openTask(t.id);history.replaceState(history.state,'','#tool/'+toolId+'/'+encodeURIComponent(t.id)+'/'+mode);render();}}}catch{/* Malformed or removed history follows the normal tool entry. */}

// Keep record maintenance and full configuration available within task information.
const trInfoBase=tcInfo;
tcInfo=function(t){const html=trInfoBase(t);if(modalData.monitor||tcMerge(t))return html;const root=document.createElement('div');root.innerHTML=html;const note=root.querySelector('.tc-modal-note');if(note){note.classList.add('tr-info-maintenance');note.innerHTML=B('修改备注','tc-notes','ghost sm','data-id="'+E(t.id)+'"')+(tcBusy(t)?B('终止任务','tc-stop','ghost danger sm','data-id="'+E(t.id)+'"'):B('删除记录','delete-task','ghost danger sm','data-id="'+E(t.id)+'"'));}if(tcView.infoTab==='config'&&tcResolve(t))root.querySelector('.tc-info-tabs')?.insertAdjacentHTML('afterend','<div class="tr-full-config">'+B('查看完整执行配置','tr-config','sm','data-id="'+E(t.id)+'"')+'</div>');return root.innerHTML;};

function trOperations(t){const merged=tcMerge(t),ready=merged?t.status==='completed'&&!!t.artifacts?.length:trHasResult(t),downloadable=merged?ready:trCanDownload(t),reason=tcBusy(t)?'任务尚未完成':!tcResolve(t)?'工具类型待确认':'暂无可查看结果';return trAction('查看结果','','tr-result',t,ready?'':reason,ready?'查看'+(TR_OUTPUTS[tcResolve(t)]?.[0]||'分析结果'):reason)+trAction('任务信息','','tr-info',t,'','查看任务状态、分析资料与执行配置')+trAction('导出数据','','tr-download',t,downloadable?'':ready?'暂无可导出数据，或资料权限已变化':reason,'选择数据范围与导出格式');}
